create table if not exists public.products(id text primary key,name text not null,level text not null,format text not null,type text not null check(type in ('download','online')),price_kes integer not null check(price_kes>0),description text not null,weeks integer not null default 0);create table if not exists public.orders(id bigint generated by default as identity primary key,order_ref text unique not null,user_id uuid not null references auth.users(id) on delete cascade,product_id text not null references public.products(id),product_name text not null,amount_kes integer not null,status text not null default 'pending' check(status in ('pending','paid','cancelled','refunded')),provider text,provider_session_id text,paid_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());create index if not exists orders_user_idx on public.orders(user_id);create table if not exists public.product_access(id bigint generated by default as identity primary key,user_id uuid not null references auth.users(id) on delete cascade,product_id text not null references public.products(id),order_id bigint not null references public.orders(id) on delete cascade,granted_at timestamptz not null default now(),unique(user_id,product_id));alter table public.products enable row level security;alter table public.orders enable row level security;alter table public.product_access enable row level security;drop policy if exists products_public_read on public.products;create policy products_public_read on public.products for select using(true);drop policy if exists orders_own_read on public.orders;create policy orders_own_read on public.orders for select using(auth.uid()=user_id);drop policy if exists access_own_read on public.product_access;create policy access_own_read on public.product_access for select using(auth.uid()=user_id);insert into public.products(id,name,level,format,type,price_kes,description,weeks) values('TOOL-001','Security Assessment Toolkit','Professional','Download','download',1500,'A starter pack of security assessment worksheets, evidence checklists and reporting templates.',0),('TR-001','Security Fundamentals','Foundational','Self-paced','online',2500,'A practical foundation in security concepts, authentication, common attack classes, and defensive thinking.',4),('TR-002','Networking for Security','Foundational','Self-paced','online',3000,'TCP/IP, DNS, routing and firewalls explained from a defensive, hands-on perspective.',5),('TR-003','Linux for Security Practitioners','Foundational','Self-paced','online',3000,'Command-line fluency, permissions, logging and process management for security work.',4),('TR-010','Secure Web Development','Intermediate','Cohort','online',6500,'Build safer authentication, validation and session handling with real code-review exercises.',6),('TR-011','Cloud Security Foundations','Intermediate','Cohort','online',7000,'IAM, network segmentation and cloud misconfiguration patterns across AWS, Azure and GCP.',6),('TR-012','Log Analysis & Detection Engineering','Intermediate','Cohort','online',6500,'Turn raw logs into useful detections, tune noise and build an alert triage workflow.',5),('TR-013','Vulnerability Management','Intermediate','Self-paced','online',4500,'Build a scanning and remediation program from CVSS scoring to practical SLAs.',4),('TR-020','Incident Response & Digital Forensics','Advanced','Cohort','online',9500,'End-to-end incident handling, evidence preservation, containment and reporting.',8),('TR-021','Threat Modeling for Architects','Advanced','Cohort','online',8500,'Apply STRIDE and attack trees to real system designs in a structured design-review workshop.',5),('TR-022','Security Leadership & Program Building','Advanced','Cohort','online',10000,'Build a risk register, budget a security program and communicate clearly with leadership.',6),('TR-023','Applied Cryptography Concepts','Advanced','Self-paced','online',7500,'Understand encryption, hashing and key management and how implementations fail.',6) on conflict(id) do update set name=excluded.name,level=excluded.level,format=excluded.format,type=excluded.type,price_kes=excluded.price_kes,description=excluded.description,weeks=excluded.weeks;
